import{_ as e,o as t,c as i,a6 as s}from"./chunks/framework.De615z8S.js";const _=JSON.parse('{"title":"插画、漫画与创意项目","description":"","frontmatter":{"id":"illustration","title":"插画、漫画与创意项目","chapter":"09","status":"已公开","evidence_status":"按原稿重写并核对官方操作资料；未执行生图、软件操作或平台上传","last_modified":"2026-10-14T00:00:00.000Z","resource_ids":[],"order":35,"content_kind":"任务入门"},"headers":[],"relativePath":"information-creative/illustration.md","filePath":"information-creative/illustration.md"}'),n={name:"information-creative/illustration.md"};function o(r,a,l,p,c,d){return t(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="插画、漫画与创意项目-先做一页再扩系列" tabindex="-1">插画、漫画与创意项目，先做一页再扩系列 <a class="header-anchor" href="#插画、漫画与创意项目-先做一页再扩系列" aria-label="Permalink to &quot;插画、漫画与创意项目，先做一页再扩系列&quot;">​</a></h1><p>本节做一页三格“咖啡店开门准备”漫画的制作计划，得到角色设定、分格脚本、单格任务词和排版文案。角色为虚构，系列实测图尚未生成。</p><h2 id="_1-每格写一个可见动作" tabindex="-1">1. 每格写一个可见动作 <a class="header-anchor" href="#_1-每格写一个可见动作" aria-label="Permalink to &quot;1. 每格写一个可见动作&quot;">​</a></h2><p>第一格打开店门，第二格摆杯子，第三格擦柜台。固定同一短发店员、圆框眼镜、米白衬衫和深蓝围裙，环境是同一家浅色咖啡店。对白在文字层加入，避免三格模型每格换脸或写错字。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>为一页三格咖啡店准备漫画整理脚本。主角为虚构店员，短发、圆框眼镜、米白衬衫、深蓝围裙，环境为同一家浅色咖啡店。</span></span>
<span class="line"><span>三格分别是打开店门、摆杯子、擦柜台。逐格输出镜头远近、人物位置、可见动作、必要道具、留给对白的空白和短文案。不要增加背景故事、人物经历和广告内容。角色与画风保持一致，单格图片与文字分别制作。</span></span></code></pre></div><h2 id="_2-单格图逐张做" tabindex="-1">2. 单格图逐张做 <a class="header-anchor" href="#_2-单格图逐张做" aria-label="Permalink to &quot;2. 单格图逐张做&quot;">​</a></h2><p>先生成角色基准，再以基准做每格，参考<a href="./../people-space/people">人物一致性</a>。动作要能看见，例如擦柜台时抹布与手接触台面，不能只让人物站着。门、柜台、杯子位置前后对应。</p><h2 id="_3-拼页与返工" tabindex="-1">3. 拼页与返工 <a class="header-anchor" href="#_3-拼页与返工" aria-label="Permalink to &quot;3. 拼页与返工&quot;">​</a></h2><p>用图层文件排三格，统一边距和对白样式。检查阅读顺序、人物服饰、道具数量、动作连续性。某格画面不对只返工该格，准确对白改文字层。系列扩展保留角色设定和场景清单，不能用一页看起来相似证明长期一致。</p><p>实际图片、可编辑拼页与阅读验证尚未制作；本页是任务入门。</p>`,10)])])}const u=e(n,[["render",o]]);export{_ as __pageData,u as default};
